from itertools import permutations

riders = ["R", "S", "T", "Y"]
bikes = ["F", "G", "H", "J"]

def valid(d1, d2):
    for r in riders:
        if d1[r] == d2[r]:
            return False
    for d in (d1, d2):
        if d["R"] == "F":
            return False
        if d["Y"] == "J":
            return False
    if "H" not in (d1["T"], d2["T"]):
        return False
    if d2["S"] != d1["Y"]:
        return False
    return True

sols = []
for p1 in permutations(bikes):
    d1 = dict(zip(riders, p1))
    if d1["T"] != "J":
        continue
    for p2 in permutations(bikes):
        d2 = dict(zip(riders, p2))
        if valid(d1, d2):
            sols.append((d1, d2))

opts = {
    "A": lambda d1, d2: d2["R"] == "G",
    "B": lambda d1, d2: d1["S"] == "H",
    "C": lambda d1, d2: d2["Y"] == "H",
    "D": lambda d1, d2: "J" in (d1["S"], d2["S"]),
    "E": lambda d1, d2: "G" in (d1["T"], d2["T"]),
}

print("number of scenarios with Theresa on J day 1:", len(sols))
possible = []
for k, f in opts.items():
    ok = [s for s in sols if f(*s)]
    print(k, "possible" if ok else "impossible", len(ok))
    if ok:
        possible.append(k)
        print("  example:", ok[0])

print("Possible options:", possible)
submitted = "A"
if possible == [submitted]:
    print("CHECK PASS")
else:
    print("CHECK FAIL")
